python -c "import csv, numpy as np, spglib; from pymatgen.core import Structure; rows=list(csv.DictReader(open('nlo_pool.csv'))); print('Parsed candidates:',len(rows)); print('ID formula SG(point group) at tolerance 0.001 A; alternatives at 0.01/0.1 A; volume/atom');
for r in rows:
 s=Structure.from_str(r['poscar'],fmt='poscar'); cell=(s.lattice.matrix,s.frac_coords,s.atomic_numbers); ds=[spglib.get_symmetry_dataset(cell,symprec=t) for t in [0.001,0.01,0.1]]; d=ds[0]; inv=any(np.array_equal(rot,-np.eye(3,dtype=int)) for rot in d.rotations); print(r['candidate_id'],r['formula'],f'{d.international} #{d.number} ({d.pointgroup})', 'CENTRO' if inv else 'NCS', '/'.join(x.international for x in ds[1:]), f'V/atom={s.volume/len(s):.2f}')"

python -c "import csv, numpy as np, spglib; from pymatgen.core import Structure; ids={'c030','c038','c048','c055','c062','c065','c066','c069','c070','c072','c073','c080','c083','c087','c090'}; anions={'S','Se','Te','As','P','Br'};
for r in csv.DictReader(open('nlo_pool.csv')):
 if r['candidate_id'] not in ids: continue
 s=Structure.from_str(r['poscar'],fmt='poscar'); ds=spglib.get_symmetry_dataset((s.lattice.matrix,s.frac_coords,s.atomic_numbers),symprec=0.01); print('\n'+r['candidate_id']+' '+r['formula']+' '+ds.international); seen=set()
 for i,site in enumerate(s):
  e=site.specie.symbol
  if ds.equivalent_atoms[i] in seen or e in {'Li','Na','K','Rb','Cs','Ca','Ba'}: continue
  seen.add(ds.equivalent_atoms[i]); targets=({'S'} if e in {'Sb','As','Te'} and any(x.specie.symbol=='S' for x in s) else anions)
  if e in anions and not (e in {'Sb','As','Te'} and any(x.specie.symbol=='S' for x in s)): continue
  ns=sorted([n for n in s.get_neighbors(site,4.5) if n.specie.symbol in targets],key=lambda n:n.nn_distance); cutoff=ns[0].nn_distance*1.25; near=[n for n in ns if n.nn_distance<cutoff]; dirs=np.array([(n.coords-site.coords)/n.nn_distance for n in near]); print(e,i,'bonds',[(n.specie.symbol,round(n.nn_distance,3)) for n in near], 'unit-bond sum',np.round(dirs.sum(axis=0),3).tolist())"

python -c "import csv, numpy as np; from collections import defaultdict; from pymatgen.core import Structure; ids={'c030','c038','c048','c055','c062','c065','c066','c069','c070','c072','c073','c080','c083','c087','c090'}; centers={'Cd','Si','Tl','Sb','Al','Ga','B','Nb','Y','Cu','Ag','Te','Hg','In','As','Ta'}; anions={'S','Se','Te','As','P','Br'};
for r in csv.DictReader(open('nlo_pool.csv')):
 if r['candidate_id'] not in ids: continue
 s=Structure.from_str(r['poscar'],fmt='poscar'); ts=defaultdict(list)
 for site in s:
  e=site.specie.symbol
  if e not in centers: continue
  if e in anions and not (e in {'As','Te'} and any(x.specie.symbol=='S' for x in s)): continue
  targets={'S'} if e in {'Sb','As','Te'} else anions; ns=sorted([n for n in s.get_neighbors(site,4.5) if n.specie.symbol in targets],key=lambda n:n.nn_distance); near=[n for n in ns if n.nn_distance<ns[0].nn_distance*1.25]; dirs=np.array([(n.coords-site.coords)/n.nn_distance for n in near]); ts[e].append(np.einsum('ni,nj,nk->ijk',dirs,dirs,dirs))
 print(r['candidate_id'],r['formula'])
 for e,arr in ts.items():
  total=np.sum(arr,axis=0); align=np.linalg.norm(total)/sum(np.linalg.norm(t) for t in arr); print(' ',e,'rank3 coherence',round(align,3),'max geometric component / volume',round(np.max(np.abs(total))/s.volume,5))"

